"""
C2 n=500 analysis: integrity checks, paired statistics, dose-response, discrimination.

Usage:
  python -m pacs.profiling.analyze_n500 --model deepseek
  python -m pacs.profiling.analyze_n500 --model qwen
  python -m pacs.profiling.analyze_n500 --model deepseek --n50-only   # dry-run with n=50 data
"""

import argparse
import json
import sys
from collections import Counter
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

import numpy as np
from scipy import stats

BASE = Path("/root/autodl-tmp/pacs")
OUT_DIR = BASE / "analysis_output"

MODELS = {"deepseek": "ds", "qwen": "qw"}
METHODS = ["imp", "rand"]
SPARSITY_LABELS = ["s015", "s020", "s025", "s030"]
SPARSITY_VALUES = {"s015": 0.15, "s020": 0.20, "s025": 0.25, "s030": 0.30}
SPARSITY_KEYS = {"s015": "0.15", "s020": "0.2", "s025": "0.25", "s030": "0.3"}
PHASES = ["high", "mid", "low"]

B_BOOTSTRAP = 10000
SEED = 42


# ── Path helpers ─────────────────────────────────────────────────────

def result_dir(model_short: str, method: str, slabel: str, n500: bool) -> Path:
    prefix = "n500_bf16" if n500 else "bf16"
    return BASE / f"profiling_output_{prefix}_{model_short}_{method}_{slabel}"


def load_json(dirpath: Path) -> Optional[dict]:
    fpath = dirpath / "profiling_results.json"
    if not fpath.exists():
        return None
    with open(fpath) as f:
        return json.load(f)


# ── Data integrity ───────────────────────────────────────────────────

def check_integrity(data: dict, expected_n: int, label: str) -> dict:
    """Validate data integrity for one condition."""
    report = {
        "label": label,
        "status": "OK",
        "warnings": [],
        "errors": [],
    }

    config_n = data.get("config", {}).get("n_problems", None)
    ppi = data.get("per_problem_ii", {})
    levels = list(ppi.keys())
    if not levels:
        report["status"] = "ERROR"
        report["errors"].append("No per_problem_ii data found")
        return report

    problems = ppi[levels[0]]
    actual_n = len(problems)

    # Check count
    if actual_n != expected_n:
        report["errors"].append(
            f"Expected {expected_n} problems, got {actual_n}"
        )
        report["status"] = "ERROR"

    if config_n is not None and config_n != expected_n:
        report["warnings"].append(
            f"Config n_problems={config_n}, expected {expected_n}"
        )

    # Check problem_idx monotonicity
    indices = [p["problem_idx"] for p in problems]
    non_monotonic = []
    for i in range(1, len(indices)):
        if indices[i] <= indices[i - 1]:
            non_monotonic.append((i, indices[i - 1], indices[i]))
    if non_monotonic:
        report["status"] = "WARNING"
        report["warnings"].append(
            f"Non-monotonic problem_idx at {len(non_monotonic)} positions "
            f"(first: pos {non_monotonic[0][0]}, "
            f"{non_monotonic[0][1]} -> {non_monotonic[0][2]}). "
            f"Possible cross-write contamination."
        )

    # Check for gaps in problem_idx
    expected_indices = set(range(actual_n))
    actual_indices = set(indices)
    if actual_indices != expected_indices and len(actual_indices) == actual_n:
        missing = expected_indices - actual_indices
        extra = actual_indices - expected_indices
        if missing:
            report["warnings"].append(f"Missing problem_idx: {sorted(missing)[:10]}...")
        if extra:
            report["warnings"].append(f"Unexpected problem_idx: {sorted(extra)[:10]}...")

    # Check duplicate problem_id
    pids = [p["problem_id"] for p in problems]
    pid_counts = Counter(pids)
    duplicates = {k: v for k, v in pid_counts.items() if v > 1}
    if duplicates:
        report["status"] = "ERROR"
        report["errors"].append(
            f"Duplicate problem_ids: {len(duplicates)} IDs appear >1 time. "
            f"First: {list(duplicates.items())[:3]}"
        )

    # Check for NaN/None values in II
    nan_count = 0
    for p in problems:
        for phase in PHASES:
            v = p.get(f"ii_{phase}")
            if v is None or (isinstance(v, float) and np.isnan(v)):
                nan_count += 1
    if nan_count > 0:
        report["warnings"].append(f"{nan_count} NaN/None II values across phases")

    if report["errors"]:
        report["status"] = "ERROR"
    elif report["warnings"]:
        report["status"] = "WARNING"

    return report


def print_integrity_report(reports: List[dict]) -> None:
    print("\n" + "=" * 70)
    print("DATA INTEGRITY REPORT")
    print("=" * 70)
    for r in reports:
        icon = {"OK": "OK", "WARNING": "WARN", "ERROR": "ERR"}[r["status"]]
        print(f"  [{icon:>4}] {r['label']}")
        for w in r["warnings"]:
            print(f"         WARN: {w}")
        for e in r["errors"]:
            print(f"         ERR:  {e}")
    n_err = sum(1 for r in reports if r["status"] == "ERROR")
    n_warn = sum(1 for r in reports if r["status"] == "WARNING")
    print(f"\n  Summary: {len(reports)} conditions, {n_err} errors, {n_warn} warnings")
    if n_err > 0:
        print("  ** ERRORS FOUND — results may be unreliable **")
