    return ppi[levels[0]]


def get_phase_ii_array(problems: List[dict], phase: str) -> np.ndarray:
    return np.array([p[f"ii_{phase}"] for p in problems if p.get(f"ii_{phase}") is not None])


# ── Per-condition statistics ─────────────────────────────────────────

def bootstrap_ci(values: np.ndarray, stat_fn, B: int = B_BOOTSTRAP,
                 alpha: float = 0.05, seed: int = SEED) -> Tuple[float, float]:
    rng = np.random.RandomState(seed)
    n = len(values)
    boot = np.array([stat_fn(values[rng.randint(0, n, size=n)]) for _ in range(B)])
    boot = boot[~np.isnan(boot)]
    if len(boot) == 0:
        return float("nan"), float("nan")
    return (
        float(np.percentile(boot, 100 * alpha / 2)),
        float(np.percentile(boot, 100 * (1 - alpha / 2))),
    )


def compute_condition_stats(problems: List[dict]) -> dict:
    """Per-condition II statistics across phases."""
    result = {"n": len(problems), "phases": {}}
    for phase in PHASES:
        vals = get_phase_ii_array(problems, phase)
        if len(vals) < 2:
            result["phases"][phase] = {"n": len(vals), "error": "insufficient data"}
            continue
        ci_lo, ci_hi = bootstrap_ci(vals, np.mean)
        med_ci_lo, med_ci_hi = bootstrap_ci(vals, np.median)
        result["phases"][phase] = {
            "n": len(vals),
            "mean": float(np.mean(vals)),
            "std": float(np.std(vals, ddof=1)),
            "median": float(np.median(vals)),
            "ci_mean": [ci_lo, ci_hi],
            "ci_median": [med_ci_lo, med_ci_hi],
        }

    # Phase gradient: D = ii_low - ii_high per problem
    diffs = []
    for p in problems:
        lo = p.get("ii_low")
        hi = p.get("ii_high")
        if lo is not None and hi is not None:
            diffs.append(lo - hi)
    diffs = np.array(diffs)
    if len(diffs) >= 2:
        d_z = float(np.mean(diffs) / np.std(diffs, ddof=1)) if np.std(diffs, ddof=1) > 0 else float("nan")
        dz_ci = bootstrap_ci(diffs, lambda x: np.mean(x) / np.std(x, ddof=1) if np.std(x, ddof=1) > 0 else np.nan)
        md_ci = bootstrap_ci(diffs, np.median)
        result["phase_gradient"] = {
            "mean_diff": float(np.mean(diffs)),
            "std_diff": float(np.std(diffs, ddof=1)),
            "median_diff": float(np.median(diffs)),
            "d_z": d_z,
            "d_z_ci": list(dz_ci),
            "median_diff_ci": list(md_ci),
            "n_pairs": len(diffs),
        }
    return result


# ── Paired importance vs random comparison ───────────────────────────

def paired_imp_vs_rand(imp_problems: List[dict], rand_problems: List[dict]) -> dict:
    """Compare importance vs random masking, paired by problem_id."""
    imp_by_id = {p["problem_id"]: p for p in imp_problems}
    rand_by_id = {p["problem_id"]: p for p in rand_problems}
    common = sorted(set(imp_by_id) & set(rand_by_id))

    if len(common) < 10:
