# ── Dose-response: II vs sparsity ───────────────────────────────────

def dose_response(condition_stats: dict, method: str, model_short: str) -> dict:
    """Spearman rho of II (per phase) vs sparsity level."""
    result = {}
    for phase in PHASES:
        sparsities = []
        means = []
        for sl in SPARSITY_LABELS:
            key = f"{model_short}_{method}_{sl}"
            cs = condition_stats.get(key, {})
            ph = cs.get("phases", {}).get(phase, {})
            if "mean" in ph:
                sparsities.append(SPARSITY_VALUES[sl])
                means.append(ph["mean"])
        if len(sparsities) >= 3:
            rho, p = stats.spearmanr(sparsities, means)
            result[phase] = {
                "spearman_rho": float(rho),
                "p_value": float(p),
                "n_levels": len(sparsities),
                "sparsities": sparsities,
                "means": means,
            }
        else:
            result[phase] = {"error": f"Only {len(sparsities)} levels available"}
    return result


# ── Discrimination metrics ───────────────────────────────────────────

def gini_coefficient(values: np.ndarray) -> float:
    """Gini coefficient: 0 = perfect equality, 1 = max inequality."""
    v = np.sort(np.abs(values))
    n = len(v)
    if n == 0 or v.sum() == 0:
        return float("nan")
    index = np.arange(1, n + 1)
    return float((2 * np.sum(index * v) - (n + 1) * np.sum(v)) / (n * np.sum(v)))


def discrimination_metrics(problems: List[dict]) -> dict:
    """Gini and CV of II across problems, per phase."""
    result = {}
    for phase in PHASES:
        vals = get_phase_ii_array(problems, phase)
        if len(vals) < 2:
            result[phase] = {"error": "insufficient data"}
            continue
        mean = float(np.mean(vals))
        std = float(np.std(vals, ddof=1))
        cv = std / abs(mean) if abs(mean) > 1e-10 else float("nan")
        result[phase] = {
            "gini": gini_coefficient(vals),
            "cv": cv,
            "iqr": float(np.percentile(vals, 75) - np.percentile(vals, 25)),
            "range": float(np.max(vals) - np.min(vals)),
            "n": len(vals),
        }
    return result


